# Stage 10D analysis: load lanes + 06 baseline, normalize, dedupe, report gates.
# Read-only pass -- writes nothing. Used to drive the final-ledger build.
import csv, re, sys, json
from collections import Counter, defaultdict

BASE = r"D:\timzhao\Downloads\P_FIXED\P\01\08_Hall_Coil_Hybrid_Radiation_Strategy_2026-07"
SIX = r"D:\timzhao\Downloads\P_FIXED\P\01\06\outputs\01_SOURCE_LEDGER.csv"
LANES = {
    "H": BASE + r"\evidence\10A_HYBRID_SOURCES.csv",
    "R": BASE + r"\evidence\10B_RADIATION_SOURCES.csv",
    "P": BASE + r"\evidence\10C_APPLICATION_SOURCES.csv",
}
HDR = ("source_id,citation,title,authors,year,venue,doi,url,source_type,"
       "peer_review_status,quality_tier,topic_tags,claims_supported,"
       "verification_basis,access_level,notes").split(",")

def norm_doi(d):
    d = (d or "").strip().lower()
    for p in ("https://doi.org/", "http://doi.org/", "https://dx.doi.org/",
              "http://dx.doi.org/", "doi:"):
        if d.startswith(p):
            d = d[len(p):]
    return d

def norm_title(t):
    t = (t or "").lower()
    t = re.sub(r"[^a-z0-9 ]+", " ", t)
    return re.sub(r"\s+", " ", t).strip()

def load(path):
    with open(path, encoding="utf-8-sig", newline="") as f:
        rows = list(csv.DictReader(f))
    return rows

def main():
    six = load(SIX)
    six_by_doi = {}
    six_by_title = {}
    for r in six:
        six_by_doi.setdefault(norm_doi(r["doi"]), r["source_id"])
        six_by_title.setdefault(norm_title(r["title"]), r["source_id"])
    print(f"06 baseline: {len(six)} rows, {len(six_by_doi)} unique normalized DOIs")

    lane_rows = {}
    for k, p in LANES.items():
        lane_rows[k] = load(p)
        hdr = list(lane_rows[k][0].keys())
        assert hdr == HDR, f"header mismatch in lane {k}: {hdr}"
        print(f"lane {k}: {len(lane_rows[k])} rows, header exact-match OK")

    # cross-lane duplicate detection by normalized DOI and title
    by_doi = defaultdict(list)
    by_title = defaultdict(list)
    allrows = []
    for k in ("H", "R", "P"):
        for r in lane_rows[k]:
            r["_lane"] = k
            by_doi[norm_doi(r["doi"])].append(r["source_id"])
            by_title[norm_title(r["title"])].append(r["source_id"])
            allrows.append(r)
    print("\nCross-lane DOI collisions:")
    for d, ids in sorted(by_doi.items()):
        if len(ids) > 1:
            print("  ", d, ids)
    print("Cross-lane TITLE collisions (different DOI):")
    for t, ids in sorted(by_title.items()):
        if len(ids) > 1 and len(set(norm_doi(r["doi"]) for r in allrows
                                    if r["source_id"] in ids)) > 1:
            print("  ", t[:60], ids)

    # per-row vs 06 baseline
    print("\nRows matching 06 baseline (by DOI or title):")
    n_dupe06 = 0
    for r in allrows:
        d, t = norm_doi(r["doi"]), norm_title(r["title"])
        hit = six_by_doi.get(d) or six_by_title.get(t)
        if hit:
            n_dupe06 += 1
            how = "doi" if d in six_by_doi else "title-only"
            print(f"  {r['source_id']} -> {hit} ({how})")
    print(f"total 06-overlaps: {n_dupe06}")

    # simulate final ledger: drop later duplicate of each cross-lane DOI collision
    keep, dropped = [], []
    seen = {}
    for r in allrows:
        d = norm_doi(r["doi"])
        if d in seen:
            dropped.append((r["source_id"], seen[d]))
        else:
            seen[d] = r["source_id"]
            keep.append(r)
    print(f"\nFinal unique rows after cross-lane DOI dedup: {len(keep)}")
    print("Dropped (merged into):", dropped)

    ver = [r for r in keep if r["peer_review_status"] == "verified_peer_reviewed"]
    unc = [r for r in keep if r["peer_review_status"] == "peer_review_uncertain"]
    print(f"verified_peer_reviewed: {len(ver)}   peer_review_uncertain: "
          f"{len(unc)} ({[r['source_id'] for r in unc]})")

    new_ver = [r for r in ver
               if norm_doi(r["doi"]) not in six_by_doi
               and norm_title(r["title"]) not in six_by_title]
    print(f"verified AND new vs 06: {len(new_ver)}")

    # quota mapping (conservative, deterministic)
    def tags(r): return set((r["topic_tags"] or "").split(";"))
    P_COIL = {"bdot_probe", "rogowski_coil", "pickup_coil", "rotating_coil",
              "mirnov_coil", "sensor_fusion", "hybrid_sensor_fusion",
              "integrator_drift_correction", "bdot_array"}
    P_CAL = {"calibration", "cross_calibration", "calibration_reference",
             "absolute_calibration", "nmr_reference", "nmr_crosscheck"}
    P_RAD = {"radiation", "radiation_tolerance", "gamma_irradiation",
             "radiation_environment"}
    R_CAL = {"R069", "R072", "R075", "R076"}
    def quota(r):
        q = set(); tg = tags(r); L = r["_lane"]; sid = r["source_id"]
        if L == "H" and tg & {"direct_hybrid", "coil_or_integrator"}: q.add("hybrid_coil")
        if L == "R" and tg & {"measurement_chain_coil", "measurement_chain_integrator"}: q.add("hybrid_coil")
        if L == "P" and tg & P_COIL: q.add("hybrid_coil")
        if L == "R": q.add("radiation")
        if L == "P" and tg & P_RAD: q.add("radiation")
        if L == "P": q.add("applications_alternatives")
        if L == "H" and tg & {"calibration_or_observer"}: q.add("calibration_observability")
        if L == "P" and tg & P_CAL: q.add("calibration_observability")
        if sid in R_CAL: q.add("calibration_observability")
        return q
    qc = Counter()
    for r in ver:
        for q in quota(r): qc[q] += 1
    print("\nQuota counts (verified only):", dict(qc))

    # tier / access / year / type distributions (verified, final set)
    print("\ntier:", dict(Counter(r["quality_tier"] for r in ver)))
    print("access:", dict(Counter(r["access_level"] for r in ver)))
    print("type:", dict(Counter(r["source_type"] for r in ver)))
    yrs = Counter((r["year"][:3] + "0s") for r in ver if r["year"])
    print("decades:", dict(sorted(yrs.items())))

    # dump per-row summary for the verification pass
    out = [{"id": r["source_id"], "doi": norm_doi(r["doi"]),
            "title": r["title"], "year": r["year"],
            "tier": r["quality_tier"], "status": r["peer_review_status"]}
           for r in keep]
    with open(BASE + r"\tools\rows_for_verification.json", "w", encoding="utf-8") as f:
        json.dump(out, f, indent=0)
    print(f"\nwrote rows_for_verification.json ({len(out)} rows)")

if __name__ == "__main__":
    main()

